import {
  AllSelection,
  CellSelection,
  GapSelection,
  NodeSelection,
  RangeSelection,
  selectionAtPosition,
  Selection,
  type AnySelection,
} from '../selection';
import { Node } from '../schema';
import { getNodeAtPath } from './path';
import { childOffset } from '../schema/child-offset';

export type MapAssociation = -1 | 1;

export interface MapResult {
  readonly position: number;
  readonly deleted: boolean;
  readonly deletedBefore: boolean;
  readonly deletedAfter: boolean;
  readonly deletedAcross: boolean;
}

export interface TextPoint {
  readonly path: readonly number[];
  readonly offset: number;
}

export interface NodeRange {
  readonly from: number;
  readonly to: number;
}

function validatePosition(position: number): void {
  if (!Number.isInteger(position) || position < 0) throw new RangeError(`Invalid document position: ${position}.`);
}

/**
 * Describes positional changes as repeating `start, oldSize, newSize` triples.
 * Positions use the same structural units as `Node.nodeSize`: text characters
 * occupy one unit and non-root nodes contribute opening and closing units.
 */
export class StepMap {
  static readonly empty = new StepMap([]);
  readonly ranges: readonly number[];

  constructor(ranges: readonly number[]) {
    if (ranges.length % 3 !== 0) throw new RangeError('StepMap ranges must contain start, oldSize, and newSize triples.');
    let previousEnd = -1;
    for (let index = 0; index < ranges.length; index += 3) {
      const start = ranges[index] as number;
      const oldSize = ranges[index + 1] as number;
      const newSize = ranges[index + 2] as number;
      if (![start, oldSize, newSize].every((value) => Number.isInteger(value) && value >= 0)) {
        throw new RangeError('StepMap ranges must contain non-negative integers.');
      }
      if (start < previousEnd) throw new RangeError('StepMap ranges must be ordered and non-overlapping.');
      previousEnd = start + oldSize;
    }
    this.ranges = Object.freeze([...ranges]);
  }

  map(position: number, association: MapAssociation = 1): number {
    return this.mapResult(position, association).position;
  }

  mapResult(position: number, association: MapAssociation = 1): MapResult {
    validatePosition(position);
    let offset = 0;
    for (let index = 0; index < this.ranges.length; index += 3) {
      const start = this.ranges[index] as number;
      const oldSize = this.ranges[index + 1] as number;
      const newSize = this.ranges[index + 2] as number;
      const end = start + oldSize;
      if (position < start) break;
      if (position <= end) {
        const side = oldSize === 0
          ? association
          : position === start
            ? -1
            : position === end
              ? 1
              : association;
        return {
          position: start + offset + (side < 0 ? 0 : newSize),
          deleted: position > start && position < end,
          deletedBefore: position > start,
          deletedAfter: position < end,
          deletedAcross: position > start && position < end,
        };
      }
      offset += newSize - oldSize;
    }
    return {
      position: position + offset,
      deleted: false,
      deletedBefore: false,
      deletedAfter: false,
      deletedAcross: false,
    };
  }

  invert(): StepMap {
    const inverse: number[] = [];
    let offset = 0;
    for (let index = 0; index < this.ranges.length; index += 3) {
      const start = this.ranges[index] as number;
      const oldSize = this.ranges[index + 1] as number;
      const newSize = this.ranges[index + 2] as number;
      inverse.push(start + offset, newSize, oldSize);
      offset += newSize - oldSize;
    }
    return new StepMap(inverse);
  }
}

/** Maps positions through a sequence of document-changing steps. */
export class Mapping {
  private readonly mutableMaps: StepMap[] = [];

  constructor(maps: readonly StepMap[] = []) {
    this.mutableMaps.push(...maps);
  }

  get maps(): readonly StepMap[] { return this.mutableMaps; }

  appendMap(map: StepMap): this {
    this.mutableMaps.push(map);
    return this;
  }

  map(position: number, association: MapAssociation = 1): number {
    return this.mutableMaps.reduce((mapped, stepMap) => stepMap.map(mapped, association), position);
  }

  mapResult(position: number, association: MapAssociation = 1): MapResult {
    let mapped = position;
    let deletedBefore = false;
    let deletedAfter = false;
    let deletedAcross = false;
    for (const stepMap of this.mutableMaps) {
      const result = stepMap.mapResult(mapped, association);
      mapped = result.position;
      deletedBefore ||= result.deletedBefore;
      deletedAfter ||= result.deletedAfter;
      deletedAcross ||= result.deletedAcross;
    }
    return {
      position: mapped,
      deleted: deletedAcross || (deletedBefore && deletedAfter),
      deletedBefore,
      deletedAfter,
      deletedAcross,
    };
  }
}

export interface PositionMapper {
  map(position: number, association?: MapAssociation): number;
}

/**
 * A document-independent selection snapshot that can be mapped before it is
 * resolved against a later document version.
 */
export class SelectionBookmark {
  private constructor(
    public readonly from: number,
    public readonly to: number,
    public readonly collapsedAssociation: MapAssociation = 1,
  ) {
    validatePosition(from);
    validatePosition(to);
    if (to < from) throw new RangeError('Selection bookmark ranges must be ordered.');
  }

  static fromSelection(doc: Node, selection: Selection, collapsedAssociation: MapAssociation = 1): SelectionBookmark {
    const from = textPointToPosition(doc, selection.path, selection.from);
    const to = selection.isCollapsed
      ? from
      : textPointToPosition(doc, selection.endPath, selection.to);
    return new SelectionBookmark(from, to, collapsedAssociation);
  }

  static cursor(position: number, association: MapAssociation = 1): SelectionBookmark {
    return new SelectionBookmark(position, position, association);
  }

  get isCollapsed(): boolean { return this.from === this.to; }

  map(mapping: PositionMapper): SelectionBookmark {
    if (this.isCollapsed) {
      return SelectionBookmark.cursor(mapping.map(this.from, this.collapsedAssociation), this.collapsedAssociation);
    }
    const from = mapping.map(this.from, 1);
    const to = mapping.map(this.to, -1);
    return from >= to
      ? SelectionBookmark.cursor(from, this.collapsedAssociation)
      : new SelectionBookmark(from, to, this.collapsedAssociation);
  }

  resolve(doc: Node): Selection {
    if (this.isCollapsed) {
      const point = positionToTextPoint(doc, this.from, this.collapsedAssociation);
      return Selection.cursor(point.path, point.offset);
    }
    const start = positionToTextPoint(doc, this.from, 1);
    const end = positionToTextPoint(doc, this.to, -1);
    const order = compareTextPoints(start, end);
    return order >= 0
      ? Selection.cursor(start.path, start.offset)
      : Selection.range(start.path, start.offset, end.path, end.offset);
  }

  eq(other: SelectionBookmark): boolean {
    return this.from === other.from
      && this.to === other.to
      && this.collapsedAssociation === other.collapsedAssociation;
  }
}

function compareTextPoints(left: TextPoint, right: TextPoint): number {
  const length = Math.min(left.path.length, right.path.length);
  for (let index = 0; index < length; index += 1) {
    const difference = (left.path[index] as number) - (right.path[index] as number);
    if (difference) return difference;
  }
  return left.path.length - right.path.length || left.offset - right.offset;
}

/** Converts a path/offset text point into a structural document position. */
export function textPointToPosition(doc: Node, path: readonly number[], offset: number): number {
  const target = getNodeAtPath(doc, path);
  if (!target.isText) throw new Error('Text positions must resolve to text nodes.');
  const length = target.text?.length ?? 0;
  if (!Number.isInteger(offset) || offset < 0 || offset > length) throw new RangeError(`Invalid text offset ${offset}.`);

  let node = doc;
  let position = 0;
  for (let depth = 0; depth < path.length; depth += 1) {
    const index = path[depth] as number;
    position += childOffset(node, index);
    node = node.child(index);
    if (depth < path.length - 1) {
      if (node.isText) throw new Error('A text node cannot contain a selection descendant.');
      position += 1;
    }
  }
  return position + offset;
}

/** Returns the structural range occupied by a node at `path`. */
export function nodeRangeAtPath(doc: Node, path: readonly number[]): NodeRange {
  if (!path.length) return { from: 0, to: Math.max(0, doc.nodeSize - 2) };
  let node = doc;
  let position = 0;
  for (let depth = 0; depth < path.length; depth += 1) {
    const index = path[depth] as number;
    position += childOffset(node, index);
    node = node.child(index);
    if (depth < path.length - 1) {
      if (node.isText) throw new Error('A text node cannot contain a descendant node.');
      position += 1;
    }
  }
  return { from: position, to: position + node.nodeSize };
}

/** Returns the position before a top-level child, including the end position. */
export function topLevelPosition(doc: Node, childIndex: number): number {
  if (!Number.isInteger(childIndex) || childIndex < 0 || childIndex > doc.childCount) {
    throw new RangeError(`Invalid top-level child index: ${childIndex}.`);
  }
  return childOffset(doc, childIndex);
}

/** Resolves a structural position to the nearest editable text point. */
export function positionToTextPoint(doc: Node, position: number, association: MapAssociation = 1): TextPoint {
  const point = findTextPoint(doc, position, association);
  if (!point) throw new Error('The document does not contain an editable text position.');
  return point;
}

function findTextPoint(doc: Node, position: number, association: MapAssociation): TextPoint | null {
  validatePosition(position);
  const backward = association < 0;
  const path: number[] = [];
  const candidatePath: number[] = [];
  let candidateFrom: number | undefined;
  let candidateTo = 0;
  let endpoint = false;
  const remember = (from: number, to: number): void => {
    candidatePath.length = path.length;
    for (let index = 0; index < path.length; index++) candidatePath[index] = path[index]!;
    candidateFrom = from;
    candidateTo = to;
  };
  // Text ranges are ordered. Reuse two path buffers instead of materializing
  // every leaf/path. Stop once interior, endpoint or nearest-gap choice is final.
  const visit = (node: Node, before: number, root = false): boolean => {
    if (node.isText) {
      const to = before + (node.text?.length ?? 0);
      if (position > before && position < to) { remember(before, to); return true; }
      if (position === before || position === to) {
        if (!endpoint || !backward) remember(before, to);
        endpoint = true;
        // Forward association still visits adjoining empty/marked endpoints.
        return backward;
      }
      if (before > position) {
        if (!endpoint && (!backward || candidateFrom === undefined)) remember(before, to);
        return true;
      }
      if (!endpoint) remember(before, to);
      return false;
    }
    let at = before + (root ? 0 : 1);
    for (let index = 0; index < node.childCount; index++) {
      const child = node.child(index);
      path.push(index);
      const done = visit(child, at);
      path.pop();
      if (done) return true;
      at += child.nodeSize;
    }
    return false;
  };
  visit(doc, 0, true);
  return candidateFrom === undefined ? null : { path: Object.freeze(candidatePath.slice()),
    offset: Math.max(0, Math.min(position - candidateFrom, candidateTo - candidateFrom)) };
}

// A valid structural edit may remove every text leaf, including temporarily
// between transaction steps. Never fabricate a text path or mutate content to
// recover the caret. Prefer the nearest legal block gap, forward on a tie.
function selectionWithoutText(doc: Node, position: number): AnySelection {
  let nearest: number | undefined;
  const consider = (candidate: number) => {
    if (nearest === undefined || Math.abs(candidate - position) < Math.abs(nearest - position)
      || (Math.abs(candidate - position) === Math.abs(nearest - position) && candidate > nearest)) nearest = candidate;
  };
  const visit = (node: Node, before: number, root = false): void => {
    if (node.isText) return;
    let at = before + (root ? 0 : 1);
    for (let index = 0; index <= node.childCount; index++) {
      const left = node.content[index - 1];
      const right = node.content[index];
      if ((left || right) && !left?.type.isInline && !right?.type.isInline) consider(at);
      if (right) { visit(right, at); at += right.nodeSize; }
    }
  };
  visit(doc, 0, true);
  return nearest === undefined ? new AllSelection(doc) : new GapSelection(doc, nearest, 1);
}

/** Maps any supported selection from one document version into the next. */
function findMappedNodePath(
  doc: Node,
  from: number,
  to: number | undefined,
  names: readonly string[],
): readonly number[] | null {
  let found: readonly number[] | null = null;
  doc.descendants((node, path) => {
    if (found || !names.includes(node.type.name)) return !found;
    const range = nodeRangeAtPath(doc, path);
    if (range.from === from && (to === undefined || range.to === to)) {
      found = Object.freeze([...path]);
      return false;
    }
    return true;
  });
  return found;
}

export function mapSelection(selection: AnySelection, before: Node, after: Node, map: PositionMapper): AnySelection {
  // Empty intermediate snapshots have neither a text caret nor a block gap.
  if (!after.childCount) return new AllSelection(after);
  if (selection instanceof AllSelection) return new AllSelection(after);
  if (selection instanceof RangeSelection) {
    const from = map.map(selection.structuralFrom, 1), to = map.map(selection.structuralTo, -1);
    if (selection.isCollapsed || from >= to) return selectionAtPosition(after, from);
    return new RangeSelection(after, selection.backward ? to : from, selection.backward ? from : to);
  }
  if (selection instanceof GapSelection) {
    return new GapSelection(after, map.map(selection.position, selection.association), selection.association);
  }
  if (selection instanceof NodeSelection) {
    const from = map.map(selection.structuralFrom, 1);
    const to = map.map(selection.structuralTo, -1);
    const path = from < to ? findMappedNodePath(after, from, to, [selection.nodeType]) : null;
    if (path) return new NodeSelection(after, path);
    const selectedNode = getNodeAtPath(before, selection.nodePath);
    if (selectedNode.type.isInline) {
      const point = findTextPoint(after, from, 1);
      if (!point) return selectionWithoutText(after, from);
      return Selection.cursor(point.path, point.offset);
    }
    return new GapSelection(after, from, 1);
  }
  if (selection instanceof CellSelection) {
    const anchorFrom = nodeRangeAtPath(before, selection.anchorCellPath).from;
    const headFrom = nodeRangeAtPath(before, selection.headCellPath).from;
    const cellNames = ['table_cell', 'table_header'];
    const anchor = findMappedNodePath(after, map.map(anchorFrom, 1), undefined, cellNames);
    const head = findMappedNodePath(after, map.map(headFrom, 1), undefined, cellNames);
    if (anchor && head) {
      try { return new CellSelection(after, anchor, head); }
      catch { /* Fall through to a recoverable gap. */ }
    }
    return new GapSelection(after, map.map(anchorFrom, 1), 1);
  }
  const start = textPointToPosition(before, selection.path, selection.from);
  const startPosition = map.map(start, 1);
  const mappedStart = findTextPoint(after, startPosition, 1);
  if (!mappedStart) return selectionWithoutText(after, startPosition);
  if (selection.isCollapsed) {
    return Selection.cursor(mappedStart.path, mappedStart.offset);
  }
  const end = textPointToPosition(before, selection.endPath, selection.to);
  const endPosition = map.map(end, -1);
  if (startPosition >= endPosition) {
    return Selection.cursor(mappedStart.path, mappedStart.offset);
  }
  const mappedEnd = positionToTextPoint(after, endPosition, -1);
  return Selection.range(mappedStart.path, mappedStart.offset, mappedEnd.path, mappedEnd.offset);
}
